class SubmitLoanRequestModule_AutoGenerated {
  /*find a loan request with provided request id, if the loan request is not exist, create a new loan request with provided info and save it, then the current loan request is it*/
  enterLoanInformation(
    requestid: number,
    name: string,
    loanamount: number,
    loanpurpose: string,
    income: number,
    phonenumber: number,
    postaladdress: string,
    zipcode: number,
    email: string,
    workreferences: string,
    creditreferences: string,
    checkingaccountnumber: number,
    securitynumber: number,
  ): boolean {
    /*Definition Start*/
    let obs: LoanRequest = l({
      logic: () =>
        getRepository(LoanRequest).find(
          (o: any) =>
            l({
              logic: () => o.RequestID === requestid,
              description: "o.RequestID=requestid",
            }).build().pass,
        ),
      description: "LoanRequest.allInstance()->any(o|o.RequestID=requestid)",
    }).build().pass;
    let currentLoanRequest: LoanRequest;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => true,
        description: "true",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let ob: LoanRequest;
    return l({
      execute: () => (ob = new LoanRequest()),
      description: "ob.oclIsNew()",
    })
      .and({
        execute: () =>
          l().if({
            logic: () =>
              l({
                logic: () => StandardOPs.oclIsUndefined(obs),
                description: "obs.oclIsUndefined()",
              }),
            description: "obs.oclIsUndefined()",
            then: l({
              execute: () => (currentLoanRequest = ob),
              description: "currentLoanRequest=ob",
            })
              .and({
                execute: () => (ob.RequestID = requestid),
                description: "ob.RequestID=requestid",
              })
              .and({
                execute: () => (ob.Name = name),
                description: "ob.Name=name",
              })
              .and({
                execute: () => (ob.LoanAmount = loanamount),
                description: "ob.LoanAmount=loanamount",
              })
              .and({
                execute: () => (ob.LoanPurpose = loanpurpose),
                description: "ob.LoanPurpose=loanpurpose",
              })
              .and({
                execute: () => (ob.Income = income),
                description: "ob.Income=income",
              })
              .and({
                execute: () => (ob.PhoneNumber = phonenumber),
                description: "ob.PhoneNumber=phonenumber",
              })
              .and({
                execute: () => (ob.PostalAddress = postaladdress),
                description: "ob.PostalAddress=postaladdress",
              })
              .and({
                execute: () => (ob.ZipCode = zipcode),
                description: "ob.ZipCode=zipcode",
              })
              .and({
                execute: () => (ob.Email = email),
                description: "ob.Email=email",
              })
              .and({
                execute: () => (ob.WorkReferences = workreferences),
                description: "ob.WorkReferences=workreferences",
              })
              .and({
                execute: () => (ob.CreditReferences = creditreferences),
                description: "ob.CreditReferences=creditreferences",
              })
              .and({
                execute: () =>
                  (ob.CheckingAccountNumber = checkingaccountnumber),
                description: "ob.CheckingAccountNumber=checkingaccountnumber",
              })
              .and({
                execute: () => (ob.SecurityNumber = securitynumber),
                description: "ob.SecurityNumber=securitynumber",
              })
              .and({
                execute: () => true,
                description: "result=true",
              }),
            else: l({
              execute: () => (currentLoanRequest = obs),
              description: "currentLoanRequest=obs",
            }).and({
              execute: () => true,
              description: "result=true",
            }),
          }),
        description:
          "(ifobs.oclIsUndefined()thencurrentLoanRequest=obandob.RequestID=requestidandob.Name=nameandob.LoanAmount=loanamountandob.LoanPurpose=loanpurposeandob.Income=incomeandob.PhoneNumber=phonenumberandob.PostalAddress=postaladdressandob.ZipCode=zipcodeandob.Email=emailandob.WorkReferences=workreferencesandob.CreditReferences=creditreferencesandob.CheckingAccountNumber=checkingaccountnumberandob.SecurityNumber=securitynumberandresult=trueelsecurrentLoanRequest=obsandresult=trueendif)",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { SubmitLoanRequestModule_AutoGenerated };

